mapper.select:
SELECT id, member_id, order_id, payment_id, amount
FROM point_earn_log
WHERE status IN ('PENDING', 'FAILED')
  AND id > #{lastId}
ORDER BY id ASC
LIMIT #{chunkSize}

mapper.update:
UPDATE point_balance
SET balance = #{balance}, updated_at = NOW(6)
WHERE member_id = #{memberId}

UPDATE point_earn_log
SET status = 'RESOLVED', resolved_at = NOW(6), updated_at = NOW(6)
WHERE id = #{id}

UPDATE point_earn_log
SET status = 'FAILED', updated_at = NOW(6)
WHERE id = #{id}
